std::vector<Polygon2d> extractArrangementFaces(const Arrangement2& arr) {
    std::vector<Polygon2d> faces;
    for (auto fit = arr.face_begin(); fit != arr.face_end(); ++fit) {
        if (fit->is_unbounded()) continue;
        Polygon2d face;
        for (auto eit = fit->outer_ccb_begin(); eit != fit->outer_ccb_end(); ++eit) {
            face.push_back(eit->source()->point());
        }
        faces.push_back(face);
    }
    return faces;
}

